import { gs } from '@servicenow/glide';
export function validateRequiredFields(current, previous) {
    var requestType = current.getValue('request_type');
    if (requestType === 'onboarding' && !current.getValue('joining_date')) {
        gs.addErrorMessage('Joining Date is required for Onboarding requests');
        current.setAbortAction(true);
    }
    if (requestType === 'offboarding' && !current.getValue('exit_date')) {
        gs.addErrorMessage('Exit Date is required for Offboarding requests');
        current.setAbortAction(true);
    }
}
